import{_ as t,g as a,e as r,a4 as o}from"./chunks/framework.CEYJDsBW.js";const m=JSON.parse('{"title":"Template Projection and Export Location","description":"","frontmatter":{},"headers":[],"relativePath":"en/ageratum/21.1/packs/export.md","filePath":"en/ageratum/21.1/packs/export.md"}'),n={name:"en/ageratum/21.1/packs/export.md"};function c(s,e,d,i,l,p){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="template-projection-and-export-location" tabindex="-1">Template Projection and Export Location <a class="header-anchor" href="#template-projection-and-export-location" aria-label="Permalink to &quot;Template Projection and Export Location&quot;">​</a></h1><p>To project the same structure with the client command, place the compressed binary template at <code>assets/workshop/ageratum/stands/basic.nbt</code>. After pressing F3+T, run the following command in-game:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/ageratum structure workshop:stands/basic ~ ~ ~</span></span></code></pre></div><p>The command index only scans <code>.nbt</code> files under <code>ageratum/</code>, stripping the folder prefix and extension to form the template ID. This differs from the direct resource path used by the <code>structure</code> tag in body text. The template manager receives raw NBT during client reload and loads it into a <code>StructureTemplate</code> using the current world&#39;s block registry when an actual projection request arrives. Templates cannot be instantiated before entering a world. <a href="https://github.com/Anvil-Dev/Ageratum/blob/83f89c4c3a6796d16bcef7e728f4b5b95d5a516c/src/main/java/dev/anvilcraft/resource/ageratum/client/feat/structure/AgeratumStructureTemplateManager.java" target="_blank" rel="noreferrer">Template registration &amp; lazy loading</a> · <a href="https://github.com/Anvil-Dev/Ageratum/blob/83f89c4c3a6796d16bcef7e728f4b5b95d5a516c/src/main/java/dev/anvilcraft/resource/ageratum/client/command/AgeratumCommand.java" target="_blank" rel="noreferrer">Projection command</a></p><h2 id="exporting-from-a-page" tabindex="-1">Exporting from a Page <a class="header-anchor" href="#exporting-from-a-page" aria-label="Permalink to &quot;Exporting from a Page&quot;">​</a></h2><p>After opening a loaded structure preview and clicking the export button, the client compresses the full structure and sends it in chunks to the server. The server validates total size, chunk order, identifier, and NBT structure, then writes it to <code>data/ageratum/</code> under the <strong>current world directory</strong>. The exported filename keeps only the namespace and the last segment of the source file: for example, <code>workshop:ageratum/en_us/maintenance/stand.snbt</code> is saved as <code>workshop_stand.nbt</code>, and subsequent exports become <code>workshop_stand_1.nbt</code>, <code>workshop_stand_2.nbt</code>, and so on.</p><table tabindex="0"><thead><tr><th>Limit</th><th>Value</th><th>Handling</th></tr></thead><tbody><tr><td>Single transfer</td><td>Max 8 MiB compressed</td><td>Checked on both client and server.</td></tr><tr><td>Per chunk</td><td>Max 24 KiB</td><td>Server requires the next chunk offset to equal the bytes received so far.</td></tr><tr><td>Decompression read budget</td><td>64 MiB</td><td>Parsed with a bounded NBT reader.</td></tr><tr><td>Request interval &amp; timeout</td><td>At least 2 seconds per player; 30-second transfer limit</td><td>Timed-out transfers are cleaned up.</td></tr></tbody></table><p>The export location is an output directory inside the save. To ship the result in the next resource pack release, copy the file into <code>assets/workshop/ageratum/</code> in your resource pack and reference its template ID. <a href="https://github.com/Anvil-Dev/Ageratum/blob/83f89c4c3a6796d16bcef7e728f4b5b95d5a516c/src/main/java/dev/anvilcraft/resource/ageratum/client/feat/structure/StructureExportClient.java" target="_blank" rel="noreferrer">Client export</a> · <a href="https://github.com/Anvil-Dev/Ageratum/blob/83f89c4c3a6796d16bcef7e728f4b5b95d5a516c/src/main/java/dev/anvilcraft/resource/ageratum/network/StructureExportHandler.java" target="_blank" rel="noreferrer">Server validation</a> · <a href="https://github.com/Anvil-Dev/Ageratum/blob/83f89c4c3a6796d16bcef7e728f4b5b95d5a516c/src/main/java/dev/anvilcraft/resource/ageratum/structure/StructureExporter.java" target="_blank" rel="noreferrer">File naming</a></p>',8)])])}const h=t(n,[["render",c]]);export{m as __pageData,h as default};
